-- app_user: Staff, operator, auditor or service-account user of the console and back-office APIs
CREATE TABLE app_user (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  username                     varchar(120) NOT NULL,
  email                        varchar(320) NOT NULL,
  first_name                   varchar(120) NOT NULL,
  last_name                    varchar(120) NOT NULL,
  display_name                 varchar(160),
  phone                        varchar(20),
  user_type                    varchar(40) NOT NULL DEFAULT 'STAFF' CHECK (user_type IN ('STAFF', 'PLATFORM_OPERATOR', 'AGENT_STAFF', 'AUDITOR', 'SERVICE_ACCOUNT')),
  status                       varchar(40) NOT NULL DEFAULT 'INVITED' CHECK (status IN ('INVITED', 'ACTIVE', 'LOCKED', 'SUSPENDED', 'DEACTIVATED')),
  sso_provider_id              uuid REFERENCES sso_provider(id),
  external_subject             varchar(255),
  legal_entity_id              uuid,
  branch_id                    uuid,
  department                   varchar(120),
  job_title                    varchar(120),
  manager_id                   uuid REFERENCES app_user(id),
  locale                       varchar(10) NOT NULL DEFAULT 'en',
  timezone                     varchar(64) NOT NULL DEFAULT 'UTC',
  password_hash                varchar(255),
