COMMENT ON COLUMN user_session.created_by IS 'Principal that created the row';
COMMENT ON COLUMN user_session.updated_at IS 'Last update time';
COMMENT ON COLUMN user_session.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN user_session.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN user_session.user_id IS 'User';
COMMENT ON COLUMN user_session.auth_method IS 'PASSWORD, SSO_OIDC, SSO_SAML, PASSKEY';
COMMENT ON COLUMN user_session.mfa_verified IS 'MFA completed';
COMMENT ON COLUMN user_session.ip_address IS 'Client IP';
COMMENT ON COLUMN user_session.user_agent IS 'Browser user agent';
COMMENT ON COLUMN user_session.device_fingerprint IS 'Device fingerprint';
COMMENT ON COLUMN user_session.geo_country IS 'Country resolved from IP';
COMMENT ON COLUMN user_session.started_at IS 'Session start';
COMMENT ON COLUMN user_session.last_seen_at IS 'Last activity';
COMMENT ON COLUMN user_session.expires_at IS 'Absolute expiry';
COMMENT ON COLUMN user_session.revoked_at IS 'Revocation time';
COMMENT ON COLUMN user_session.revoke_reason IS 'Revocation reason';
COMMENT ON COLUMN user_session.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN user_session.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN user_session.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN user_session.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN user_session.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_user_session_tenant ON user_session (tenant_id, created_at);
CREATE INDEX ix_user_session_user_id ON user_session (user_id);
ALTER TABLE user_session ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON user_session USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_user_session_touch BEFORE UPDATE ON user_session FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA identity TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA identity TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA identity GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
